// Ahorro de la casa: «ver» trae el saldo y los movimientos; «inicial» guarda con cuánto empezaron; «meta» guarda la meta.
// Los depósitos y retiros son movimientos normales de Notion con categoría Ahorro (Gasto = se guardó, Ingreso = se sacó).
const it = $input.first().json;
let b = it.body;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
b = b || {};
if (b.token !== 'mercado-7d41c2a9e05b') return [{ json: { ok: false, error: 'token' } }];
const accion = ['ver', 'inicial', 'meta'].includes(b.accion) ? b.accion : 'ver';
const valor = Math.round(Number(b.valor));
if (accion !== 'ver' && !(valor >= 0 && valor <= 1e11)) return [{ json: { ok: false, error: 'valor' } }];
const fecha = /^\d{4}-\d{2}-\d{2}$/.test(String(b.fecha || '')) ? String(b.fecha) : null;
return [{ json: { ok: true, accion, valor, fecha } }];

// Lee una propiedad venga como página completa de Notion (properties) o simplificada de n8n (property_xxx)
const clave = (n) => 'property_' + String(n).toLowerCase().replace(/\s+/g, '_');
const txt = (a) => ((a || []).map(t => t.plain_text).join('') || '').trim();
const leer = (it, nombre, tipo) => {
  const pr = it.properties && it.properties[nombre];
  if (pr) {
    if (tipo === 'titulo') return txt(pr.title);
    if (tipo === 'texto') return txt(pr.rich_text);
    if (tipo === 'numero') return pr.number != null ? pr.number : null;
    if (tipo === 'fecha') return pr.date && pr.date.start ? pr.date.start.slice(0, 10) : null;
    if (tipo === 'select') return pr.select ? pr.select.name : (pr.status ? pr.status.name : null);
    if (tipo === 'relacion') return pr.relation && pr.relation[0] ? pr.relation[0].id : null;
  }
  let v = it[clave(nombre)];
  if (v === undefined && tipo === 'titulo') v = it.name;
  if (v === undefined || v === null || v === '') return null;
  if (tipo === 'fecha') { const s = typeof v === 'object' ? (v.start || '') : String(v); return s ? s.slice(0, 10) : null; }
  if (tipo === 'relacion') { const r = Array.isArray(v) ? v[0] : v; return r ? (typeof r === 'object' ? r.id : String(r)) : null; }
  if (tipo === 'numero') return typeof v === 'number' ? v : (Number(v) || null);
  return String(v);
};

const v = $('Validar').first().json;
const sd = $getWorkflowStaticData('global');
if (v.accion === 'inicial') { sd.inicial = v.valor; sd.inicialFecha = v.fecha || new Date(Date.now() - 5 * 3600 * 1000).toISOString().slice(0, 10); }
if (v.accion === 'meta') sd.meta = v.valor;
const movs = $input.all().map(i => i.json).filter(x => x && x.id && leer(x, 'Categoría', 'select') === 'Ahorro')
  .map(x => {
    const tipo = leer(x, 'Tipo', 'select'), monto = leer(x, 'Monto', 'numero') || 0;
    return { id: x.id, fecha: leer(x, 'Fecha', 'fecha') || '', concepto: leer(x, 'Concepto', 'titulo') || 'Ahorro', nota: leer(x, 'Notas', 'texto') || '', monto: tipo === 'Ingreso' ? -monto : monto };
  })
  .filter(m => m.fecha && (!sd.inicialFecha || m.fecha >= sd.inicialFecha))   // lo de antes del saldo inicial ya está incluido en él
  .sort((a, b) => b.fecha.localeCompare(a.fecha));
const movido = movs.reduce((a, m) => a + m.monto, 0);
return [{ json: { ok: true, inicial: sd.inicial || 0, inicialFecha: sd.inicialFecha || null, meta: sd.meta || 0, saldo: (sd.inicial || 0) + movido, movimientos: movs.slice(0, 200) } }];
